<script setup lang="ts">
import {ArrowLeft,ArrowRight,BookOpen,Minus,Plus,X,Sun,Moon,Bookmark,Heart,Check} from 'lucide-vue-next'
import type {LibraryBook} from '~/data/library/catalog'
import {splitReadingPages} from '~/utils/library/navigation'
const props=defineProps<{book:LibraryBook}>(),emit=defineEmits<{close:[]}>()
const {library,toggleBook}=useProgress()
const {records,storageNotice,load,savePage,saveBookmark,removeBookmark}=useLibraryReading()
const note=ref(''),showBookmarks=ref(false),bookmarkNotice=ref('')
const marks=computed(()=>records.value[props.book.id]?.bookmarks||[])
const currentMark=computed(()=>marks.value.find(mark=>mark.page===page.value))
const dialog=ref<HTMLDialogElement>(),body=ref<HTMLElement>(),loading=ref(true),error=ref(''),pages=ref<string[]>([]),page=ref(0),fontSize=ref(19),paper=ref(false)
const controller=new AbortController()
const paragraphs=computed(()=>(pages.value[page.value]||'').split(/\n\s*\n/))
function preserveNote(){if(!loading.value&&!error.value&&note.value!==(currentMark.value?.note||''))saveBookmark(props.book.id,page.value,note.value)}
function go(value:number){preserveNote();page.value=Math.max(0,Math.min(pages.value.length-1,value));body.value?.scrollTo({top:0});savePage(props.book.id,page.value);note.value=currentMark.value?.note||'';bookmarkNotice.value=''}
onMounted(async()=>{
 paper.value=document.documentElement.classList.contains('factum-light');load(props.book.id);dialog.value?.showModal()
 try{
  const full=await $fetch<string>(props.book.file,{responseType:'text',signal:controller.signal})
  const start=full.match(/\*\*\* START OF (?:THE|THIS) PROJECT GUTENBERG EBOOK[^\n]*\*\*\*/i)
  const content=start?full.slice((start.index||0)+start[0].length).split(/\*\*\* END OF (?:THE|THIS) PROJECT GUTENBERG EBOOK/i)[0]!:full
  pages.value=splitReadingPages(content.trim(),4400)
  page.value=Math.min(records.value[props.book.id]?.page||0,pages.value.length-1);note.value=currentMark.value?.note||'';savePage(props.book.id,page.value)
 }catch(e){if(!controller.signal.aborted)error.value='Գիրքը չհաջողվեց բեռնել։ Փակիր և փորձիր կրկին։'}finally{loading.value=false}
})
onUnmounted(()=>{preserveNote();controller.abort();dialog.value?.close()})
function keyboard(e:KeyboardEvent){if(['SELECT','INPUT','TEXTAREA'].includes((e.target as HTMLElement).tagName))return;if(e.key==='ArrowRight'){e.preventDefault();go(page.value+1)}if(e.key==='ArrowLeft'){e.preventDefault();go(page.value-1)}}
</script>
<template>
 <dialog ref="dialog" class="book-reader" :class="{paper}" aria-labelledby="reader-title" @cancel.prevent="emit('close')" @keydown="keyboard" @click="($event.target===dialog)&&emit('close')">
  <header><div><small>FACTUM · ԸՆԹԵՐՑԱՍՐԱՀ</small><h2 id="reader-title">{{book.title}}</h2><p>{{book.author}} · {{book.language}}</p></div><button type="button" aria-label="Փակել գիրքը" @click="emit('close')"><X :size="21"/></button></header>
  <nav class="reader-tools" aria-label="Ընթերցման կարգավորումներ"><span><BookOpen :size="15"/>Հայերեն ամբողջական բնագիր</span><div><button type="button" :disabled="fontSize<=16" aria-label="Փոքրացնել տառերը" @click="fontSize=Math.max(16,fontSize-1)"><Minus :size="16"/></button><span>{{fontSize}}</span><button type="button" :disabled="fontSize>=28" aria-label="Մեծացնել տառերը" @click="fontSize=Math.min(28,fontSize+1)"><Plus :size="16"/></button><button type="button" :aria-label="paper?'Մուգ ընթերցման ֆոն':'Բաց ընթերցման ֆոն'" @click="paper=!paper"><Moon v-if="paper" :size="17"/><Sun v-else :size="17"/></button></div></nav>
  <div class="reader-personal-tools"><button type="button" :aria-pressed="library.includes(book.id)" @click="toggleBook(book.id)"><Heart :size="15" :fill="library.includes(book.id)?'currentColor':'none'"/>{{library.includes(book.id)?'Սիրված է':'Ավելացնել սիրվածներին'}}</button><button type="button" :aria-expanded="showBookmarks" @click="showBookmarks=!showBookmarks"><Bookmark :size="15"/>Էջանշաններ · {{marks.length}}</button><span v-if="currentMark"><Check :size="13"/>Էջանշված էջ</span></div>
  <section v-if="showBookmarks" class="reader-bookmarks" aria-label="Գրքի էջանշաններն ու նշումները"><div class="bookmark-editor"><label>Նշում այս էջի համար<textarea v-model="note" maxlength="1000" rows="2" placeholder="Ինչի՞ն ես ուզում վերադառնալ…"/></label><button type="button" :disabled="loading" @click="saveBookmark(book.id,page,note);bookmarkNotice='Էջանշանն ու նշումը պահպանված են։'"><Bookmark :size="14"/>{{currentMark?'Թարմացնել էջանշանը':'Էջանշել այս էջը'}}</button><span role="status">{{bookmarkNotice}}</span></div><div class="bookmark-list"><p v-if="!marks.length">Այս գրքում դեռ էջանշան չկա։</p><div v-for="mark in marks" :key="mark.page"><button type="button" @click="go(mark.page)"><strong>Էջ {{mark.page+1}}</strong><span>{{mark.note||'Էջանշան'}}</span></button><button type="button" :aria-label="`Հեռացնել ${mark.page+1}-րդ էջի էջանշանը`" @click="removeBookmark(book.id,mark.page)"><X :size="14"/></button></div></div></section>
  <div ref="body" class="reader-body" :style="{fontSize:fontSize+'px'}" lang="hy" tabindex="0"><p v-if="loading" class="reader-status">Բեռնվում է միայն ընտրված գիրքը…</p><p v-else-if="error" role="alert" class="reader-status">{{error}}</p><template v-else><p v-for="(paragraph,i) in paragraphs" :key="page+':'+i" class="reading-paragraph">{{paragraph}}</p></template></div>
  <footer><div class="reader-pagination"><button type="button" :disabled="loading||page===0" @click="go(page-1)"><ArrowLeft :size="16"/>Նախորդ</button><label>Էջ <select :value="page" :disabled="loading" aria-label="Ընտրել ընթերցման էջը" @change="go(Number(($event.target as HTMLSelectElement).value))"><option v-for="(_,i) in pages" :key="i" :value="i">{{i+1}}</option></select> / {{pages.length||'…'}}</label><button type="button" :disabled="loading||page>=pages.length-1" @click="go(page+1)">Հաջորդ<ArrowRight :size="16"/></button></div><p v-if="storageNotice" role="status">Բրաուզերը չի թույլատրում պահպանել․ նշումները հիմա հասանելի են միայն այս բացված էջում։</p><p v-else>Ընթերցման տեղը և էջանշանները պահպանվում են այս սարքում։ <a :href="book.source" target="_blank" rel="noopener noreferrer">Տեքստի աղբյուրը ↗</a></p><p class="reader-attribution">{{book.textLicense}} · <a v-if="book.textLicense.includes('CC BY-SA')" href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">Արտոնագիր ↗</a></p></footer>
 </dialog>
</template>
<style scoped>
.reader-personal-tools{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:10px 28px;border-bottom:1px solid var(--reader-line)}.reader-personal-tools button,.reader-personal-tools>span{display:flex;align-items:center;gap:7px;font-size:10px;color:#c4a774}.reader-personal-tools button{border:1px solid var(--reader-line);border-radius:8px;padding:8px 11px}.reader-personal-tools button[aria-pressed=true]{background:#d6b87b15;color:#e2bb77}.reader-bookmarks{display:grid;grid-template-columns:1fr 1fr;gap:18px;padding:15px 28px;border-bottom:1px solid var(--reader-line);max-height:230px;overflow:auto;font-size:10px}.bookmark-editor label{display:grid;gap:8px;color:var(--reader-muted)}.bookmark-editor textarea{width:100%;background:var(--reader-bg);color:var(--reader-text);border:1px solid var(--reader-line);border-radius:7px;padding:9px;font:inherit;resize:vertical}.bookmark-editor>button{display:flex;align-items:center;gap:7px;padding:8px 10px;margin-top:9px;color:#bc9c61;border:1px solid var(--reader-line);border-radius:7px}.bookmark-editor>span{display:block;margin-top:7px;color:var(--reader-muted)}.bookmark-list>div{display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid var(--reader-line);padding:8px 0}.bookmark-list>div>button:first-child{text-align:left;display:grid;gap:5px;min-width:0;flex:1}.bookmark-list strong{color:#bc9c61;font-size:10px}.bookmark-list span{color:var(--reader-muted);white-space:pre-wrap;overflow-wrap:anywhere;font-size:9px}.bookmark-list>p{color:var(--reader-muted);line-height:1.8}@media(max-width:600px){.reader-personal-tools{padding:9px 15px}.reader-bookmarks{grid-template-columns:1fr;padding:12px 16px;max-height:230px}.reader-personal-tools button{font-size:9px}}

.book-reader{--reader-bg:#111f30;--reader-text:#d9e0e8;--reader-line:#8395aa35;--reader-muted:#a1afbc;position:fixed;inset:0;margin:auto;width:min(960px,calc(100vw - 28px));height:min(900px,calc(100dvh - 36px));max-height:calc(100dvh - 36px);padding:0;border:1px solid #c4a96c70;border-radius:18px;background:var(--reader-bg);color:var(--reader-text);box-shadow:0 30px 100px #0008;overflow:hidden}.book-reader[open]{display:flex;flex-direction:column}.book-reader::backdrop{background:#020a16d6;backdrop-filter:blur(8px)}.book-reader.paper{--reader-bg:#f5efdf;--reader-text:#352f27;--reader-line:#5e4c2a33;--reader-muted:#786c59}.book-reader header{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;padding:23px 30px 19px;border-bottom:1px solid var(--reader-line)}header small{font-size:8px;letter-spacing:2px;color:var(--reader-muted)}header h2{font-size:21px;font-weight:600;line-height:1.6;margin:5px 0}header p{font-size:10px;color:var(--reader-muted)}header button{padding:7px}.reader-tools{display:flex;justify-content:space-between;gap:15px;align-items:center;padding:12px 30px;border-bottom:1px solid var(--reader-line);font-size:10px;color:var(--reader-muted)}.reader-tools>span,.reader-tools>div{display:flex;gap:13px;align-items:center}.reader-tools button{padding:5px}.reader-body{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;padding:36px max(32px,8%);line-height:1.85;font-family:'Noto Sans Armenian',sans-serif}.reading-paragraph{white-space:pre-wrap;margin-bottom:1.15em;overflow-wrap:anywhere}.reader-status{font:13px 'Noto Sans Armenian',sans-serif;text-align:center;padding:50px 0;color:var(--reader-muted)}footer{padding:14px 28px;border-top:1px solid var(--reader-line)}.reader-pagination{display:flex;justify-content:space-between;align-items:center;gap:15px;font-size:11px}.reader-pagination button{display:flex;align-items:center;gap:8px;padding:7px}.reader-pagination label{display:flex;align-items:center;gap:7px;color:var(--reader-muted)}.reader-pagination select{background:var(--reader-bg);border:1px solid var(--reader-line);border-radius:5px;padding:5px;color:var(--reader-text)}footer>p{font-size:8px;line-height:1.8;color:var(--reader-muted);margin-top:9px;text-align:center}footer a{text-decoration:underline}button:disabled{opacity:.3}button:focus-visible,select:focus-visible,.reader-body:focus-visible{outline:2px solid #b2945d;outline-offset:3px}@media(max-width:600px){.book-reader{width:calc(100vw - 14px);height:calc(100dvh - 16px);max-height:calc(100dvh - 16px);border-radius:11px}.book-reader header{padding:17px 18px 14px}header h2{font-size:17px}.reader-tools{padding:9px 15px;font-size:8px}.reader-tools>span{max-width:160px;line-height:1.6}.reader-body{padding:25px 21px}footer{padding:10px 12px}.reader-pagination{font-size:9px;gap:4px}footer>p{font-size:7px}}
</style>
